//! `ferrum-alloy openapi export`: produces the OpenAPI artifact and detects
//! drift.
//!
//! The document comes from the project's own `openapi` binary (generated by
//! `ferrum-alloy new --with openapi`), run with `cargo run --bin openapi`
//! through an explicit argument list (no shell), or from `--input`. With
//! `--manifest`, `servers` is set to the manifest's gateway-facing
//! `public_path`, and stripped service base paths are removed from operations.
//!
//! The written document is held to `MAX_OUTPUT_BYTES`: pretty-printing can
//! make it several times larger than its compact input, but not without
//! bound. `--check` compares parsed documents and renders nothing.
//!
//! AI-agent tool metadata (`x-ferrum-mcp`, see
//! [`ferrum_alloy_edge::agents`]): the manifest's `[agents]` section becomes
//! the document-level extension, exposed operations get their method's
//! default MCP annotations, and metadata Ferrum Edge would reject or an agent
//! could not use fails the export and `--check` with exit 3. A hand-written
//! selection that publishes every `GET` operation is a warning.

use std::collections::BTreeMap;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::process::{Command, ExitCode, Stdio};

use clap::{Args, Subcommand};
use serde_json::Value;

use crate::error::CliError;
use crate::input::{ReadError, describe, invalid, read_regular_file_bounded};

/// `openapi` subcommands.
#[derive(Debug, Subcommand)]
pub(crate) enum OpenapiCommand {
    /// Export (or `--check`) the OpenAPI document.
    Export(ExportArgs),
}

/// Arguments for `openapi export`.
#[derive(Debug, Args)]
pub(crate) struct ExportArgs {
    /// Project directory containing Cargo.toml.
    #[arg(long, default_value = ".")]
    project: PathBuf,
    /// Binary that prints the document.
    #[arg(long, default_value = "openapi")]
    bin: String,
    /// Read the document from this file instead of running the project.
    #[arg(long)]
    input: Option<PathBuf>,
    /// Service manifest; sets `servers` to `api.public_path`, maps stripped base paths, and
    /// stamps `[agents]` as the document-level `x-ferrum-mcp`.
    #[arg(long)]
    manifest: Option<PathBuf>,
    /// Output file.
    #[arg(long, default_value = "openapi.json")]
    output: PathBuf,
    /// Compare with the existing output instead of writing; exit 4 on drift.
    #[arg(long)]
    check: bool,
}

const MAX_DOCUMENT_BYTES: u64 = 16 * 1024 * 1024;
/// Most bytes `openapi export` writes, and reads back for `--check`: four
/// times the input limit, room for indentation a real document needs.
const MAX_OUTPUT_BYTES: usize = 64 * 1024 * 1024;

fn load(args: &ExportArgs) -> Result<Vec<u8>, CliError> {
    if let Some(input) = &args.input {
        return read_regular_file_bounded(input, MAX_DOCUMENT_BYTES).map_err(|e| invalid(input, e));
    }
    if !args
        .bin
        .bytes()
        .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_'))
    {
        return Err(CliError::Invalid(
            "--bin must be a binary target name".into(),
        ));
    }
    let manifest_path = args.project.join("Cargo.toml");
    if !manifest_path.is_file() {
        return Err(CliError::Invalid(format!(
            "{} not found",
            manifest_path.display()
        )));
    }
    let cargo = std::env::var_os("CARGO").unwrap_or_else(|| "cargo".into());
    crate::eprint(&format!(
        "running: cargo run --quiet --manifest-path {} --bin {}\n",
        manifest_path.display(),
        args.bin
    ));
    let mut child = Command::new(cargo)
        .arg("run")
        .arg("--quiet")
        .arg("--manifest-path")
        .arg(&manifest_path)
        .arg("--bin")
        .arg(&args.bin)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|e| CliError::Io(format!("cannot run cargo: {e}")))?;
    // The document is held to the same limit as `--input`: read at most one
    // byte past it, so a binary that prints without end cannot exhaust memory.
    let mut stdout = Vec::new();
    let read = match child.stdout.take() {
        Some(pipe) => pipe.take(MAX_DOCUMENT_BYTES + 1).read_to_end(&mut stdout),
        None => Ok(0),
    };
    // The pipe is closed here: a child still writing gets EPIPE.
    if read.is_err() || u64::try_from(stdout.len()).unwrap_or(u64::MAX) > MAX_DOCUMENT_BYTES {
        // Best effort: the child may already have exited.
        let _ = child.kill();
        let _ = child.wait();
        return Err(match read {
            Err(e) => CliError::Io(format!(
                "cannot read `cargo run --bin {}` output: {e}",
                args.bin
            )),
            Ok(_) => CliError::Invalid(format!(
                "`cargo run --bin {}` printed more than {MAX_DOCUMENT_BYTES} bytes",
                args.bin
            )),
        });
    }
    let status = child
        .wait()
        .map_err(|e| CliError::Io(format!("cannot run cargo: {e}")))?;
    if !status.success() {
        return Err(CliError::Io(format!(
            "`cargo run --bin {}` failed ({status})",
            args.bin
        )));
    }
    Ok(stdout)
}

fn validate(document: &Value) -> Result<(), CliError> {
    let version = document
        .get("openapi")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if !version.starts_with("3.") {
        return Err(CliError::Invalid(format!(
            "not an OpenAPI 3.x document (openapi = {version:?}); Ferrum Nexus accepts only 3.x"
        )));
    }
    if !document.get("paths").is_some_and(Value::is_object) {
        return Err(CliError::Invalid(
            "OpenAPI document has no `paths` object".into(),
        ));
    }
    if !document.get("info").is_some_and(Value::is_object) {
        return Err(CliError::Invalid(
            "OpenAPI document has no `info` object".into(),
        ));
    }
    Ok(())
}

fn normalize_paths(
    document: &mut Value,
    manifest: &ferrum_alloy_edge::manifest::ServiceManifest,
) -> Result<(), CliError> {
    let Some(paths) = document.get_mut("paths").and_then(Value::as_object_mut) else {
        return Ok(());
    };
    if !manifest.api.strip_public_path || manifest.api.service_base_path == "/" {
        return Ok(());
    }

    let base_path = manifest.api.service_base_path.trim_end_matches('/');
    let mut normalized_paths = serde_json::Map::new();
    let mut renamed = BTreeMap::new();
    for (path, operations) in std::mem::take(paths) {
        let normalized = if path == base_path {
            "/"
        } else if let Some(suffix) = path.strip_prefix(base_path).filter(|s| s.starts_with('/')) {
            suffix
        } else {
            &path
        };
        if normalized != path {
            renamed.insert(path.clone(), normalized.to_owned());
        }
        if normalized_paths
            .insert(normalized.to_owned(), operations)
            .is_some()
        {
            return Err(CliError::Invalid(format!(
                "OpenAPI paths collide after removing service_base_path {base_path:?}"
            )));
        }
    }
    *paths = normalized_paths;
    if renamed.is_empty() {
        return Ok(());
    }
    // Keys moved, so local `#/paths/...` references to them broke (#224).
    // Decision (a) there: rewrite Path Item `$ref`s sitting directly under
    // `paths` — the reported alias case — and refuse the export when any
    // other `$ref`/`$dynamicRef`/`operationRef` still names a stripped
    // key, rather than writing a broken document. A false positive (a
    // `$ref`-shaped string that is data) only refuses the export.
    for (key, item) in paths.iter_mut() {
        // Extension data under `paths` is not a Path Item; a `$ref`-shaped
        // string there is refused below, never rewritten.
        if key.starts_with("x-") {
            continue;
        }
        let Some(reference) = item.get_mut("$ref") else {
            continue;
        };
        let Some(text) = reference.as_str() else {
            continue;
        };
        if let Some((segment, rest)) = paths_reference(text)
            && let Some(new) = renamed.get(pointer_unescape(segment).as_str())
        {
            *reference = Value::String(format!("#/paths/{}{rest}", pointer_escape(new)));
        }
    }
    // Reuse the rename index for the whole-document walk: each reference
    // decodes its key once and does one lookup, never a scan of every rename.
    refuse_stripped_references(document, &renamed)
}

/// The first pointer segment of a local `#/paths/...` reference and the
/// remainder after it (including its leading `/`, or empty).
fn paths_reference(text: &str) -> Option<(&str, &str)> {
    let rest = text.strip_prefix("#/paths/")?;
    match rest.find('/') {
        Some(at) => Some((&rest[..at], &rest[at..])),
        None => Some((rest, "")),
    }
}

/// JSON Pointer segment escaping (`~` then `/`, RFC 6901 §3).
fn pointer_escape(segment: &str) -> String {
    segment.replace('~', "~0").replace('/', "~1")
}

/// The inverse, in the specified order (`~1` before `~0`, so `~01` is `~1`).
fn pointer_unescape(segment: &str) -> String {
    segment.replace("~1", "/").replace("~0", "~")
}

/// Whether a reference names one of the stripped `paths` keys, after
/// decoding the whole URI fragment (RFC 6901 §6): percent-encoded
/// structural characters (`#/%70aths/...`, `...%2Fget`) decode before
/// segmenting, so no spelling of a stripped key slips past refusal.
/// Refusal matching is generous in this way, while rewriting above
/// stays on plain pointer semantics.
fn names_stripped_key(text: &str, stripped: &BTreeMap<String, String>) -> bool {
    let decoded = percent_decode(text);
    let Some((segment, _)) = paths_reference(&decoded) else {
        return false;
    };
    stripped.contains_key(pointer_unescape(segment).as_str())
}

/// Percent-decodes for comparison only (see [`names_stripped_key`]).
fn percent_decode(segment: &str) -> String {
    let bytes = segment.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut at = 0usize;
    while at < bytes.len() {
        if bytes[at] == b'%'
            && let Some(hex) = bytes.get(at + 1..at + 3)
            && let Ok(byte) = u8::from_str_radix(std::str::from_utf8(hex).unwrap_or_default(), 16)
        {
            decoded.push(byte);
            at += 3;
        } else {
            decoded.push(bytes[at]);
            at += 1;
        }
    }
    String::from_utf8_lossy(&decoded).into_owned()
}

/// Refuses when any `$ref`/`$dynamicRef`/`operationRef` string in the
/// document still names one of the stripped `paths` keys (the rewritten
/// Path Item references no longer do).
fn refuse_stripped_references(
    document: &Value,
    stripped: &BTreeMap<String, String>,
) -> Result<(), CliError> {
    let mut stack = vec![document];
    while let Some(value) = stack.pop() {
        match value {
            Value::Object(object) => {
                for (key, child) in object {
                    if matches!(key.as_str(), "$ref" | "$dynamicRef" | "operationRef")
                        && let Some(text) = child.as_str()
                        && names_stripped_key(text, stripped)
                    {
                        return Err(CliError::Invalid(format!(
                            "OpenAPI reference {text:?} names a path removed by service_base_path stripping; repoint it at the stripped path key or remove it before exporting"
                        )));
                    }
                    stack.push(child);
                }
            }
            Value::Array(items) => stack.extend(items),
            _ => {}
        }
    }
    Ok(())
}

/// A `Vec` that refuses to grow past `limit` bytes.
struct BoundedBuffer {
    bytes: Vec<u8>,
    limit: usize,
    exceeded: bool,
}

impl Write for BoundedBuffer {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        if buf.len() > self.limit.saturating_sub(self.bytes.len()) {
            self.exceeded = true;
            return Err(std::io::Error::other("output limit reached"));
        }
        self.bytes.extend_from_slice(buf);
        Ok(buf.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

/// The pretty-printed document and a final newline, at most `limit` bytes.
fn render(document: &Value, limit: usize) -> Result<Vec<u8>, CliError> {
    let mut out = BoundedBuffer {
        bytes: Vec::new(),
        limit,
        exceeded: false,
    };
    let rendered = serde_json::to_writer_pretty(&mut out, document)
        .map_err(|e| e.to_string())
        .and_then(|()| out.write_all(b"\n").map_err(|e| e.to_string()));
    match rendered {
        Ok(()) => Ok(out.bytes),
        Err(_) if out.exceeded => Err(CliError::Invalid(format!(
            "the exported document is larger than {limit} bytes once pretty-printed"
        ))),
        Err(e) => Err(CliError::Io(e)),
    }
}

/// Runs an `openapi` subcommand.
pub(crate) fn run(command: OpenapiCommand) -> Result<ExitCode, CliError> {
    let OpenapiCommand::Export(args) = command;
    let bytes = load(&args)?;
    let mut document: Value = serde_json::from_slice(&bytes)
        .map_err(|e| CliError::Invalid(format!("document is not JSON: {e}")))?;
    validate(&document)?;
    let manifest = match &args.manifest {
        Some(path) => Some(crate::edge::read_manifest(path)?),
        None => None,
    };
    if let Some(manifest) = &manifest {
        normalize_paths(&mut document, manifest)?;
        if let Some(map) = document.as_object_mut() {
            map.insert(
                "servers".into(),
                serde_json::json!([{ "url": manifest.api.public_path, "description": "Ferrum Edge public path" }]),
            );
        }
    }
    let warnings = ferrum_alloy_edge::agents::prepare(&mut document, manifest.as_ref())
        .map_err(|e| CliError::Invalid(e.to_string()))?;
    for warning in warnings {
        crate::eprint(&format!("warning: {warning}\n"));
    }
    if args.check {
        // Compared as parsed JSON, so nothing is rendered. The existing
        // output may be laid out differently and is held to the output
        // limit, which exceeds the input limit for pretty-printed text.
        let limit = u64::try_from(MAX_OUTPUT_BYTES).unwrap_or(u64::MAX);
        let existing = match read_regular_file_bounded(&args.output, limit) {
            Ok(existing) => existing,
            Err(ReadError::Io(e)) => {
                return Err(CliError::Drift(format!(
                    "{}: {e}; run without --check to create it",
                    args.output.display()
                )));
            }
            Err(e) => return Err(CliError::Drift(describe(&args.output, e))),
        };
        let existing: Value = serde_json::from_slice(&existing)
            .map_err(|e| CliError::Drift(format!("{} is not JSON: {e}", args.output.display())))?;
        if existing != document {
            return Err(CliError::Drift(format!(
                "{} is out of date with the code; run `ferrum-alloy openapi export` and commit the result",
                args.output.display()
            )));
        }
        crate::print(&format!("{} is up to date\n", args.output.display()))?;
        return Ok(ExitCode::SUCCESS);
    }
    let rendered = render(&document, MAX_OUTPUT_BYTES)?;
    crate::fsout::write_atomically(&args.output, &rendered, crate::fsout::NewFileMode::Umask)?;
    crate::eprint(&format!("wrote {}\n", args.output.display()));
    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]

    use super::*;

    #[test]
    fn rendering_stops_at_the_output_limit() {
        let document = serde_json::json!({ "a": [[[[1, 2, 3]]]] });
        let full = render(&document, MAX_OUTPUT_BYTES).unwrap();
        assert_eq!(full.last(), Some(&b'\n'));
        assert_eq!(render(&document, full.len()).unwrap(), full);
        let error = render(&document, full.len() - 1).unwrap_err();
        assert!(
            matches!(&error, CliError::Invalid(message) if message.contains("larger than")),
            "{error:?}"
        );
    }
}
